import type {
  AISuggestionListProps,
  AISuggestionProps,
  AISuggestionListLabelProps,
} from "./ai-suggestion.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { Skeleton } from "../../../skeleton";

import {
  AISuggestionListClasses,
  StyledAISuggestionList,
  AISuggestionClasses,
  StyledAISuggestion,
} from "./ai-suggestion.styles";

// --- AISuggestionListLabel ---

export const AISuggestionListLabel = forwardRef<HTMLDivElement, AISuggestionListLabelProps>(
  ({ children, className, ...props }, ref) => {
    const rootClasses = clsx(AISuggestionListClasses.label, className);

    return (
      <div ref={ref} className={rootClasses} {...props}>
        {children}
      </div>
    );
  },
);

AISuggestionListLabel.displayName = "AI.SuggestionListLabel";

// --- AISuggestionList ---

export const AISuggestionList = forwardRef<HTMLDivElement, AISuggestionListProps>(
  ({ children, className, variant = "default", ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(AISuggestionListClasses.root, className);

    return (
      <StyledAISuggestionList
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledAISuggestionList>
    );
  },
);

AISuggestionList.displayName = "AI.SuggestionList";

// --- AISuggestion ---

export const AISuggestion = forwardRef<HTMLButtonElement, AISuggestionProps>(
  (
    { children, className, type = "button", variant = "default", loading = false, ...props },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(AISuggestionClasses.root, className);

    if (loading) {
      return (
        <StyledAISuggestion
          aria-busy="true"
          as="div"
          className={rootClasses}
          currentTheme={theme}
          data-loading="true"
          variant={variant}
          {...props}
        >
          <Skeleton style={{ height: theme.toRem(12) }} />
        </StyledAISuggestion>
      );
    }

    return (
      <StyledAISuggestion
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        type={type}
        variant={variant}
        {...props}
      >
        {children}
      </StyledAISuggestion>
    );
  },
);

AISuggestion.displayName = "AI.Suggestion";
